shots.setup:
(() => {
  const reply = document.querySelector('.cv-reply:has(.cv-h2)');
  const p = reply && reply.querySelector('.cv-md p');
  if (!p) return;
  const cs = getComputedStyle(p);
  const ctx = document.createElement('canvas').getContext('2d');
  ctx.font = `${cs.fontWeight} ${cs.fontSize} ${cs.fontFamily}`;
  const text = [...reply.querySelectorAll('.cv-md p, .cv-md li')].map((e) => e.textContent).join(' ');
  const perChar = ctx.measureText(text).width / text.length;
  const width = p.getBoundingClientRect().width;
  const tag = document.createElement('div');
  tag.textContent = `measure ${Math.round(width)} px: about ${Math.round(width / perChar)} characters per line`;
  tag.style.cssText = 'margin-top:8px;font:600 13px system-ui;padding:2px 6px;background:#c62828;color:#fff;display:inline-block';
  reply.appendChild(tag);
})()
